arguments.rule_content:
{
  "title": "Detect Emotet Macro Dropper Execution",
  "id": "example-sigma-2026-0711-emotet-macro",
  "description": "Detect execution of Excel macro that drops Emotet DLL",
  "status": "experimental",
  "author": "SOC",
  "logsource": {
    "product": "windows",
    "service": "office",
    "category": "process_creation"
  },
  "detection": {
    "selection": {
      "Image": "*\\excel.exe",
      "CommandLine|contains": [".xlsm", "macro"],
      "ParentImage|endswith": ".xlsm"
    },
    "condition": "selection"
  },
  "falsepositives": ["Legitimate macro-enabled Excel files"],
  "level": "high"
}
